const qs = [
  "CreateMemo|rpc CreateMemo|Transcribe|service .*Service|ShortcutService",
  "GetUser\\(|CreateMemo\\(|DeleteMemo\\(|ListMemos\\(",
  "type .*Memo struct|type .* interface|func .*Store|NewStore|sqlite|postgres",
  "webhook|Webhook|sse|SSE|Broadcast|Schedule|runner|cron|interceptor|Bearer|access token",
  "memo CRUD|use.*Memo|MemoServiceClient|Connect"
];
const rs = await Promise.all(qs.map(cmd => tools.exec_command({cmd:`rg -n -i '${cmd}' proto server store web/src --glob '!**/*.pb.go' --glob '!**/node_modules/**' | sed -n '1,180p'`,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:12000})));
rs.forEach((r,i)=>{ text(`---${i+1}---`); text(r.output);});

const cmds = [
"nl -ba proto/api/v1/memo_service.proto | sed -n '1,180p'; nl -ba proto/api/v1/shortcut_service.proto 2>/dev/null || true",
"find store/migration -maxdepth 2 -type d | sort; find store/seed -type f | sort",
"nl -ba store/store.go | sed -n '1,180p'; nl -ba store/db/postgres/postgres.go | sed -n '1,100p'",
"rg -n '^func \\(s \\*APIV1Service\\) (CreateMemo|ListMemos|DeleteMemo|SignIn|Transcribe)|Store\\.CreateMemo|GetUser\\(' server/router/api/v1 server --glob '*.go'",
"rg -n 'CreateMemo|ListMemos|DeleteMemo|MemoServiceClient|createMemo|listMemos' web/src --glob '*.ts' --glob '*.tsx' | sed -n '1,220p'"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:12000})));
rs.forEach((r,i)=>{text(`---${i+1}---`);text(r.output)});

