"nl -ba store/memo.go | sed -n '1,190p'; nl -ba store/db/postgres/memo.go | sed -n '1,220p'",
"nl -ba server/router/api/v1/connect_handler.go; nl -ba server/router/api/v1/connect_services.go; nl -ba server/server.go | sed -n '1,240p'",
